    background: var(--panel); border: 1px solid var(--border); border-radius: 8px;
    padding: 9px 11px;
  }
  .evidence a:hover, .evidence a:focus-visible { border-color: var(--accent); outline: none; }
  .row-meta { color: var(--muted); display: block; font-size: .76rem; margin-bottom: 2px; }
  .row-title { display: block; font-size: .88rem; font-weight: 600; line-height: 1.35; }
  #tooltip {
    display: none; position: fixed; z-index: 5; max-width: min(340px, calc(100vw - 24px));
    background: var(--panel); color: var(--text); border: 1px solid var(--border);
    border-radius: 8px; box-shadow: 0 5px 18px rgba(0,0,0,.18);
    padding: 9px 11px; font-size: .82rem; line-height: 1.4; pointer-events: none;
  }
  #tooltip strong { display: block; margin-bottom: 3px; }
  @media (max-width: 480px) {
    main { padding: 14px 10px 20px; }
    .chart-card { padding: 4px; }
  }
</style>
</head>
<body>
<main>
  <h1>Slay the Spire 2 sentiment before vs. after launch</h1>
  <p class="subtitle">Stored mention counts by sentiment · exact-date records in each period</p>

  <section class="chart-card" aria-label="Grouped bar chart of sentiment counts">
    <svg id="chart" viewBox="0 0 700 405" role="img" aria-labelledby="chart-title chart-desc">
      <title id="chart-title">Mention sentiment before and after the March 5 release</title>
      <desc id="chart-desc">Positive, neutral, and negative mention counts for February 16 to March 4 and March 5 to March 20, 2026. A vertical marker labels the March 5 release date.</desc>
    </svg>
  </section>
  <p class="note">Positive mentions remained the largest category after launch. Negative mentions appear in the post-release period, with all five stored negative mentions dated March 18–20.</p>

  <h2>Negative-mention evidence</h2>
  <p class="evidence-intro">Hover or focus a row for its summary. Each item links to its stored source.</p>
  <ul class="evidence" id="evidence"></ul>
</main>
<div id="tooltip" role="status" aria-live="polite"></div>

<script>
(() => {
  const svg = document.getElementById("chart");
  const ns = "http://www.w3.org/2000/svg";
  const tooltip = document.getElementById("tooltip");

  const groups = [
    { label: "Pre-release", dates: "Feb 16–Mar 4", counts: { positive: 13, neutral: 7, negative: 0 } },
    { label: "Post-release", dates: "Mar 5–20", counts: { positive: 15, neutral: 8, negative: 5 } }
  ];
  const series = [
    { key: "positive", label: "Positive" },
    { key: "neutral", label: "Neutral" },
    { key: "negative", label: "Negative" }
  ];

  function el(name, attrs, text) {
    const node = document.createElementNS(ns, name);
    for (const [key, value] of Object.entries(attrs || {})) node.setAttribute(key, value);
    if (text !== undefined) node.textContent = text;
    return node;
  }
  function showTooltip(title, detail, x, y) {
    tooltip.replaceChildren();
    const strong = document.createElement("strong");
    strong.textContent = title;
    const body = document.createElement("span");
    body.textContent = detail;
    tooltip.append(strong, body);
    tooltip.style.display = "block";
    const left = Math.min(x + 12, window.innerWidth - tooltip.offsetWidth - 10);
    const top = Math.min(y + 12, window.innerHeight - tooltip.offsetHeight - 10);
    tooltip.style.left = Math.max(10, left) + "px";
    tooltip.style.top = Math.max(10, top) + "px";
  }
  function hideTooltip() { tooltip.style.display = "none"; }

  const plot = { left: 76, right: 674, top: 82, bottom: 306 };
  const max = 16;
  const y = value => plot.bottom - (value / max) * (plot.bottom - plot.top);

  // Horizontal count axis and labeled ticks.
  svg.append(el("text", { x: 20, y: 195, class: "axis-label", transform: "rotate(-90 20 195)", "text-anchor": "middle" }, "Mentions"));
  [0, 5, 10, 15].forEach(value => {
    const yy = y(value);
    svg.append(el("line", { x1: plot.left, y1: yy, x2: plot.right, y2: yy, class: "tick" }));
    svg.append(el("text", { x: plot.left - 12, y: yy + 4, class: "tick-label", "text-anchor": "end" }, String(value)));
  });
  svg.append(el("line", { x1: plot.left, y1: plot.bottom, x2: plot.right, y2: plot.bottom, class: "axis" }));

  // Legend.
  const legendStart = 420;
  series.forEach((item, i) => {
    const lx = legendStart + i * 84;
    svg.append(el("rect", { x: lx, y: 24, width: 12, height: 12, rx: 2, class: "legend-swatch " + item.key }));
    svg.append(el("text", { x: lx + 17, y: 35, class: "legend-label" }, item.label));
  });

  // Release-date marker, between the two period groups.
  const markerX = 375;
  svg.append(el("line", { x1: markerX, y1: 62, x2: markerX, y2: plot.bottom, class: "event-line" }));
  svg.append(el("text", { x: markerX + 7, y: 73, class: "event-label" }, "Release · March 5"));

  const centers = [222, 526];
  const barWidth = 43;
  const gap = 10;
  groups.forEach((group, gi) => {
    const totalWidth = series.length * barWidth + (series.length - 1) * gap;
    const startX = centers[gi] - totalWidth / 2;

    series.forEach((item, si) => {
      const value = group.counts[item.key];
      const x = startX + si * (barWidth + gap);
      const yy = y(value);
      const height = Math.max(0, plot.bottom - yy);
      const rect = el("rect", {
        x, y: value === 0 ? plot.bottom - 1 : yy, width: barWidth, height: value === 0 ? 1 : height,
        rx: 3, class: "bar " + item.key, tabindex: "0", role: "img",
        "aria-label": `${group.label}, ${group.dates}, ${item.label}: ${value} mentions`
      });
      const detail = `${item.label}: ${value} mentions · ${group.dates}, 2026`;
      rect.addEventListener("pointerenter", event => showTooltip(group.label, detail, event.clientX, event.clientY));
      rect.addEventListener("pointermove", event => showTooltip(group.label, detail, event.clientX, event.clientY));
      rect.addEventListener("pointerleave", hideTooltip);
      rect.addEventListener("focus", () => {
        const r = rect.getBoundingClientRect();
        showTooltip(group.label, detail, r.left + r.width / 2, r.top + r.height / 2);
      });
      rect.addEventListener("blur", hideTooltip);
      svg.append(rect);
      svg.append(el("text", {
        x: x + barWidth / 2, y: value === 0 ? plot.bottom - 8 : yy - 7,
        class: "value-label", "text-anchor": "middle"
      }, String(value)));
    });

    svg.append(el("text", { x: centers[gi], y: 335, class: "period-label", "text-anchor": "middle" }, group.label));
    svg.append(el("text", { x: centers[gi], y: 354, class: "tick-label", "text-anchor": "middle" }, group.dates + ", 2026"));
  });
  svg.append(el("text", { x: (plot.left + plot.right) / 2, y: 389, class: "axis-label", "text-anchor": "middle" }, "Release period"));

  const negativeEvidence = [
    {
      date: "2026-03-18", source: "kotaku.com",
      url: "https://kotaku.com/slay-the-spire-2-tips-tricks-beginner-deckbuilding-2000680050",
      title: "Slay The Spire 2: Tips And Tricks For Getting Started",
      summary: "Parker writes that Slay the Spire 2 can be tough for newcomers and even experienced players, pointing to player discussions and the difficulty of getting through early runs. The guide offers tips to help people survive and adapt, while describing balance concerns."
    },
    {
      date: "2026-03-20", source: "gamespot.com",
      url: "https://www.gamespot.com/articles/slay-the-spire-2-is-becoming-a-little-less-scary-but-players-are-unhappy-with-patchs-nerfs/1100-6538921/",
      title: "Slay The Spire 2 Is Becoming A Little Less Scary, But Players Are Unhappy With Patch’s Nerfs",
      summary: "Tomas Franzese covers v0.100.0, highlighting its accessibility toggle and extensive balance changes. The article says some adjustments—particularly a change to Silent’s Prepared card and a stronger Doormaker boss—have caused community backlash."
    },
    {
      date: "2026-03-20", source: "polygon.com",
      url: "https://www.polygon.com/slay-the-spire-2-patch-infinite-doormaker-prepared-card-changes-steam-reviews/",
      title: "Slay the Spire 2 slammed on Steam over patch that makes game harder",
      summary: "Polygon says the beta update made the game harder by changing popular card strategies and buffing enemies, including the final boss. It describes player anger over nerfs to infinite combos and specific changes to Silent and Regent."
    },
    {
      date: "2026-03-20", source: "kotaku.com",
      url: "https://kotaku.com/slay-the-spire-2-steam-review-bomb-balance-patch-prepared-doormaker-2000680603",
      title: "Slay The Spire 2 Is Getting Review Bombed On Steam Over Upcoming Balance Patch",
      summary: "Lewis Parker reports that the game’s Steam rating fell after a beta balance patch changed the Silent’s Prepared card and strengthened the Doormaker fight. The article says some players used reviews to express objections rather than the in-game feedback tools."
    },
    {
      date: "2026-03-20", source: "pcgamesn.com",
      url: "https://www.pcgamesn.com/slay-the-spire-2/patch-notes-infinites-nerfed",
      title: "Slay the Spire 2 is stamping out infinites, and you're not prepared for what we've lost",
      summary: "Ken Allsop describes the update as a substantial balance pass aimed at making infinite combos less accessible, while noting they remain part of the game’s power curve. The article details changes to Silent’s Prepared card and the new Phobia Mode."
    }
  ];

  const list = document.getElementById("evidence");
  negativeEvidence.forEach(item => {
    const li = document.createElement("li");
    const a = document.createElement("a");
    a.setAttribute("href", item.url);
    a.setAttribute("target", "_blank");
    a.setAttribute("rel", "noopener noreferrer");
    const meta = document.createElement("span");
    meta.className = "row-meta";
    meta.textContent = item.date + " · " + item.source + " · Negative";
    const title = document.createElement("span");
    title.className = "row-title";
    title.textContent = item.title;
    a.append(meta, title);
    const detail = item.source + " · " + item.date + " — " + item.summary;
    a.addEventListener("pointerenter", event => showTooltip(item.title, detail, event.clientX, event.clientY));
    a.addEventListener("pointermove", event => showTooltip(item.title, detail, event.clientX, event.clientY));
    a.addEventListener("pointerleave", hideTooltip);
    a.addEventListener("focus", () => {
      const r = a.getBoundingClientRect();
      showTooltip(item.title, detail, r.left + r.width / 2, r.top + Math.min(r.height / 2, 35));
    });
    a.addEventListener("blur", hideTooltip);
    li.append(a);
    list.append(li);
  });
})();
</script>
</body>
</html>"}

