      <line class="grid" x1="88" y1="50" x2="660" y2="50"></line>
      <line class="grid" x1="88" y1="106" x2="660" y2="106"></line>
      <line class="grid" x1="88" y1="162" x2="660" y2="162"></line>
      <line class="grid" x1="88" y1="218" x2="660" y2="218"></line>
      <line class="grid" x1="88" y1="274" x2="660" y2="274"></line>
      <line class="grid" x1="88" y1="330" x2="660" y2="330"></line>
      <line class="axis" x1="88" y1="50" x2="88" y2="330"></line>
      <line class="axis" x1="88" y1="330" x2="660" y2="330"></line>
