<script>
(() => {
  const plot = document.getElementById("plot");
  const tooltip = document.getElementById("tooltip");
  const groups = document.querySelectorAll(".bar-group");

  function show(group, x, y) {
    const date = group.dataset.date;
    const positive = group.dataset.positive;
    const neutral = group.dataset.neutral;
    const negative = group.dataset.negative;
    tooltip.textContent = `${date}\nPositive: ${positive} · Neutral: ${neutral} · Negative: ${negative}`;
    tooltip.style.display = "block";
    const bounds = plot.getBoundingClientRect();
    tooltip.style.left = `${Math.max(8, Math.min(x - bounds.left + 12, bounds.width - tooltip.offsetWidth - 8))}px`;
    tooltip.style.top = `${Math.max(8, y - bounds.top - tooltip.offsetHeight - 10)}px`;
  }

  groups.forEach(group => {
    group.addEventListener("pointerenter", event => show(group, event.clientX, event.clientY));
    group.addEventListener("pointermove", event => show(group, event.clientX, event.clientY));
    group.addEventListener("pointerleave", () => { tooltip.style.display = "none"; });
    group.addEventListener("focus", () => {
      const box = group.getBoundingClientRect();
      show(group, box.left + box.width / 2, box.top + box.height / 2);
